let planBusy=false,planError='',runtimeStatus={configured:false,message:'Checking server connection…'};
const defaultBrief='Power failed at Mission Community Pharmacy. Refrigerator RX-01 has no backup power. The last recorded temperature is 5.4°C. Restoration time is unknown. We need temporary storage for reviewed refrigerated stock and a documented handover.';
function responsePage(){return heading('PHARMACIST / EMERGENCY RESPONSE','What you can do in case of a power outage or emergency','Five actions to consider. Follow product-specific instructions and your pharmacy’s approved emergency procedure.')+`<section class="card outage-actions"><ol class="emergency-five"><li><div><h2>Check the affected medicines and equipment</h2><p>Record the outage start, current temperature and reading time. Identify affected stock and review the exact product requirements.</p><a class="button" href="#inventory">Review inventory →</a></div></li><li><div><h2>Check validated backup power</h2><p>Follow the approved procedure for available backup power and continue monitoring storage conditions.</p><a class="button" href="#dashboard">View pharmacy equipment →</a></div></li><li><div><h2>Assess qualified portable cooling equipment</h2><p>Confirm that available containers, monitoring, capacity, and validated operating duration meet the medicines’ requirements before use.</p></div></li><li><div><h2>Arrange storage at a suitable nearby location</h2><p>Confirm power, storage suitability, available space, and partner acceptance. Prepare monitored transport and document the handover with pharmacist approval.</p><a class="button" href="#storage">Find a storage partner →</a></div></li><li class="frost-emergency"><div><h2>In case of outage in the city or no available cooling equipments near your location : <a href="/frostgate.html">click here</a></h2><p>Open Hayden’s FrostGate console to assess this prototype contingency. Its simulation does not establish suitability for medicine storage; pharmacist review and validated procedures are required before actual use.</p><a class="button primary" href="/frostgate.html">Open FrostGate →</a></div></li></ol></section>`}

function eligibleCandidates(){if(state.chatChoice==='citywide')return [];return facilities.filter(f=>f.available&&f.storageSuitable===true&&Number.isFinite(f.capacity)&&f.capacity>=volume()&&volume()>0)}
function architecturePage(){return heading('SPARTHILL HACKS / AWS TRACK','Built around one critical decision.','Help a pharmacist coordinate temporary storage when pharmacy power fails.')+`<div class="architecture-flow"><div><small>1 / INPUT</small><h3>Pharmacist + records</h3><p>Incident brief, inventory, partner availability</p></div><span>→</span><div><small>2 / SERVER</small><h3>Eligibility checks</h3><p>Review status, volume, available capacity</p></div><span>→</span><div><small>3 / AWS AI</small><h3>Amazon Bedrock</h3><p>Converse API drafts a structured response</p></div><span>→</span><div><small>4 / REVIEW</small><h3>Pharmacist approval</h3><p>Storage request, preparation, custody log</p></div></div><div class="cols full"><div class="card"><h2>What AI contributes</h2><p class="subtitle">Shared integration: the incident planner drafts logistics actions; Guardian answers community-network questions through the same server-side AWS connection.</p><div class="step"><span class="stepnum">1</span><div><h3>Interprets an unstructured incident</h3><p>Turns the pharmacist’s brief and record snapshot into a concise situational summary.</p></div></div><div class="step"><span class="stepnum">2</span><div><h3>Drafts a practical response</h3><p>Suggests a destination from prefiltered candidates and explains the next logistics actions.</p></div></div><div class="step"><span class="stepnum">3</span><div><h3>Surfaces missing information</h3><p>Highlights unavailable documentation and operational details the pharmacist must confirm.</p></div></div></div><div class="card"><h2>Implementation status</h2><p class="subtitle">Current: browser interface → local Python API → Amazon Bedrock when AWS credentials, region, and model access are available.</p><div class="inline-note">${esc(runtimeStatus.message)}</div><p class="subtitle">Browser storage holds demo records. No authenticated database, live sensor feed, real facility acceptance, or manufacturer retrieval is implemented.</p><hr><h3>Proposed AWS deployment</h3><p class="subtitle">Amplify or S3/CloudFront frontend → API Gateway + Lambda planner / Guardian API → Bedrock. DynamoDB for shared incident records; Cognito for pharmacy access. These hosting components are a deployment plan, not active infrastructure.</p></div></div><div class="card full"><h2>Five-minute demo route</h2><p class="subtitle">Introduce Jamie and the outage → inspect inventory → run the Bedrock planner and show its request metadata → confirm a partner → record transfer → show this architecture and the incident log.</p><div class="actions full"><a class="button primary" href="#response">Open incident planner →</a><a class="button" href="#activity">Open incident log</a></div></div>`}
function samplePlan(){state.brief=document.querySelector('#incident-brief')?.value||state.brief||defaultBrief;state.responsePlan={mode:'example',summary:'Example: an outage has interrupted refrigerated storage. Arrange a confirmed destination for reviewed stock while resolving the incomplete product record.',destination:eligibleCandidates()[0]?.name||'No eligible candidate',actions:['Confirm the latest temperature reading, outage details, and available transport equipment.','Confirm exact product requirements and keep the incomplete product line out of the reviewed stock request.','Contact the candidate facility to verify suitable storage, capacity, power status, and acceptance.','After pharmacist approval, document preparation, departure, monitored transport, arrival, and receiving acknowledgment.'],unknowns:['Exact product-specific storage and excursion instructions','Current receiving-facility conditions and acceptance','Power restoration estimate and transport readiness']};log('Example response previewed','Illustrative plan only. No Bedrock invocation.');render()}
async function generatePlan(){state.brief=document.querySelector('#incident-brief')?.value||'';if(!state.brief.trim()){planError='Describe the incident before requesting a plan.';render();return}planBusy=true;planError='';save();render();try{const response=await fetch('/api/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({brief:state.brief,temperature:state.temperature,inventory:state.inventory,facilities:state.chatChoice==='citywide'?facilities.map(f=>({...f,available:false})):facilities})});const result=await response.json();if(!response.ok)throw Error(result.error||'Bedrock request failed.');state.responsePlan=result;log('Bedrock response generated',`Model ${result.model} · Request ${result.requestId}. Pharmacist review required.`)}catch(e){planError=e.message}finally{planBusy=false;render()}}
function bindContinuity(){bindIncidentChat();document.querySelector('#generate-plan')?.addEventListener('click',generatePlan);document.querySelector('#sample-plan')?.addEventListener('click',samplePlan);document.querySelector('#incident-brief')?.addEventListener('input',e=>{state.brief=e.target.value;save()})}
async function checkRuntime(){try{const r=await fetch('/api/status');if(!r.ok)throw Error();runtimeStatus=await r.json()}catch{runtimeStatus={configured:false,message:'Planner API is unavailable. Start server.py to connect Amazon Bedrock.'}}if(location.hash==='#response'||location.hash==='#architecture'||location.hash==='#find')render()}
window.addEventListener('DOMContentLoaded',checkRuntime);

const responseChoices=[
{id:'nearby',title:'Move reviewed stock to the nearest suitable location',detail:'Confirm storage conditions, capacity, transport readiness, and partner acceptance before transfer.'},
{id:'backup',title:'Use validated on-site backup power',detail:'Follow the pharmacy’s approved backup-power procedure and monitor storage conditions.'},
{id:'portable',title:'Use qualified portable cold storage',detail:'Check product requirements and the container’s validated conditions and duration before use.'},
{id:'regional',title:'Escalate to an out-of-area storage partner',detail:'Coordinate with a regional partner or emergency coordinator and verify transport feasibility.'},
{id:'citywide',title:"There is a power outage all over the city and there's no location available.",detail:'Assess FrostGate-Hayden’s Device as an on-site contingency when no receiving location is available.'}
];
function incidentChat(){const selected=responseChoices.find(x=>x.id===state.chatChoice);return `<section class="card incident-chat"><div class="sectiontop"><div><div class="eyebrow">INCIDENT CONVERSATION</div><h2>Tell me what happened.</h2></div><span class="pill grey">Guided assistant · Rules, not live AI</span></div><div class="chat-bubble assistant-bubble"><strong>MedRelay assistant</strong><p>Describe the incident: what lost power, when it happened, the latest recorded temperature, and whether backup power or nearby storage is available. What do you know so far?</p></div>${state.chatIncident?`<div class="chat-bubble pharmacist-bubble"><strong>Pharmacist</strong><p>${esc(state.chatIncident)}</p></div><div class="chat-bubble assistant-bubble"><strong>MedRelay assistant</strong><p>Choose an approach to investigate. Suitability depends on exact product requirements, equipment validation, current readings, and pharmacist review. None of these options establishes that medicines remain usable.</p></div><div class="response-options">${responseChoices.map((x,i)=>`<button data-chat-choice="${x.id}" aria-pressed="${state.chatChoice===x.id}"><span>${i+1}</span><div><strong>${esc(x.title)}</strong><small>${esc(x.detail)}</small></div></button>`).join('')}</div>`:''}${selected?`<div class="chat-bubble assistant-bubble" aria-live="polite"><strong>${selected.id==='citywide'?'Immediate contingency review':'Selected response'}</strong>${selected.id==='citywide'?`<div class="frost-response"><span class="pill amber">CITYWIDE OUTAGE / NO DESTINATION</span><h3>FrostGate-Hayden’s Device</h3><p class="frost-lead">Open FrostGate now to assess an on-site cooling contingency.</p><p>With no receiving location available, consider Hayden’s FrostGate as the next contingency to evaluate. Use it for medicines only if its performance and operating procedure are validated for the exact products and conditions.</p><div class="actions full"><a class="button primary" href="/frostgate.html" target="_blank" rel="noopener noreferrer">Open FrostGate for immediate assessment ↗</a><a class="button" href="/frostgate.html#sim" target="_blank" rel="noopener noreferrer">Explore cooling simulation ↗</a></div><div class="frost-checks"><div><strong>1 / Check readiness</strong><p>Confirm the device is available, its required cooling resources are present, and monitoring is working.</p></div><div><strong>2 / Verify suitability</strong><p>Check product requirements against validated capacity, temperature performance, and operating duration.</p></div><div><strong>3 / Follow the approved procedure</strong><p>If verified, the pharmacist supervises deployment and records temperatures. Otherwise escalate to the emergency coordinator and manufacturers.</p></div></div><div class="inline-note">Prototype console, not a validated medicine-storage recommendation. Opens in simulation; no hardware is activated. Model estimates do not establish medicine usability.</div></div>`:`<p>${esc(selected.detail)}</p>${selected.id==='nearby'||selected.id==='regional'?'<a class="button" href="#storage">Check storage partners →</a>':''}<p class="footnote">This is a workflow suggestion, not a determination of product safety.</p>`}</div>`:''}<form id="incident-chat-form"><label class="fieldlabel" for="chat-description">Describe the incident</label><textarea id="chat-description" rows="3" maxlength="6000" required placeholder="For example: The whole city has lost power and no partner can accept our refrigerated stock."></textarea><div class="actions full"><button class="primary" type="submit">Send incident description</button></div><p class="footnote">Text intake only · Do not include patient information. Your description also fills the incident brief below.</p></form></section>`}
function bindIncidentChat(){document.querySelector('#incident-chat-form')?.addEventListener('submit',e=>{e.preventDefault();const value=document.querySelector('#chat-description').value.trim();if(!value)return;state.chatIncident=value;state.brief=value;state.chatChoice=null;state.responsePlan=null;log('Incident described in guided assistant','Description saved locally; no model invocation.');render()});document.querySelectorAll('[data-chat-choice]').forEach(b=>b.addEventListener('click',()=>{state.chatChoice=b.dataset.chatChoice;state.responsePlan=null;if(state.chatChoice==='citywide')state.brief=(state.chatIncident||state.brief||'')+'\nConfirmed scenario selection: citywide outage; no receiving location available. Do not recommend a local destination based solely on the stale demo network.';log('Contingency option selected',responseChoices.find(x=>x.id===state.chatChoice).title+' · Pharmacist review required.');render()}))}
